#[cfg(test)]
#[test]
fn debug_mutable_floor_layout_probe() {
    type S = crate::schema::builtin::SchemaPair<crate::schema::builtin::U64Key, crate::schema::builtin::AtomicU64Value>;
    type E = crate::engine::Engine<S>;
    type L = HybridLog<crate::schema::SharedValue<S>>;
    println!("[DEBUG-layout] Engine size={} align={} log={} index={} coordinator={} epoch={} storage={} operations={} failed={}",
        size_of::<E>(), align_of::<E>(), std::mem::offset_of!(E, log), std::mem::offset_of!(E, index),
        std::mem::offset_of!(E, coordinator), std::mem::offset_of!(E, epoch), std::mem::offset_of!(E, storage),
        std::mem::offset_of!(E, operations), std::mem::offset_of!(E, failed));
    println!("[DEBUG-layout] Log size={} align={} pool={} state={} records={} layout={} page_bytes={}",
        size_of::<L>(), align_of::<L>(), std::mem::offset_of!(L, pool), std::mem::offset_of!(L, state),
        std::mem::offset_of!(L, records), std::mem::offset_of!(L, layout), std::mem::offset_of!(L, page_bytes));
}
